// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testRegression_property() public {
        c.initialize(
            address(1),
            address(2),
            100 ether,
            10 ether,
            100,
            100,
            bytes32(0),
            false,
            false
        );

        bool secondCallReverted;
        try c.initialize(
            address(1),
            address(2),
            100 ether,
            10 ether,
            100,
            100,
            bytes32(0),
            false,
            false
        ) {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        assertTrue(secondCallReverted);
    }
}
